def max_nonoverlapping(intervals: list) -> int:
    if not intervals:
        return 0
    intervals_sorted = sorted(intervals, key=lambda x: x[1])
    count = 0
    last_end = float('-inf')
    for s, e in intervals_sorted:
        if s >= last_end:
            count += 1
            last_end = e
    return count
```

